const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),request=require('supertest');
const {createAuthenticatedActionApp}=require('./authenticated-app.cjs');
const {FORMAT}=require('./action-state.cjs');
let directory,app,alice,bob,state,revision,privateRef;
async function save(){const old=(await alice.get('/api/action-state')).body;const result=await alice.put('/api/action-state').set('If-Match',old.revision).send({format:FORMAT,data:state});expect(result.status).toBe(200);revision=result.body.revision}
async function share(action='publish',consent=true,extra={}){const plan=await alice.get('/api/review-target-sharing').query({nodeId:'my-goal'});let q=alice.post('/api/review-target-sharing').set('If-Match','"'+revision+'"');if(plan.body.revision)q=q.set('If-Target-Match',plan.body.revision);return q.send({nodeId:'my-goal',sourceVersion:state.nodes[0].version,action,consent,...extra})}
beforeEach(async()=>{directory=fs.mkdtempSync(path.join(os.tmpdir(),'dianliang-target-sharing-'));app=createAuthenticatedActionApp({dataDir:directory,reviewDirectory:path.join(directory,'assets'),rateLimitEnabled:false}).app;alice=request.agent(app);bob=request.agent(app);await alice.post('/api/register').send({name:'sharing-alice',password:'test-only-2026'});await bob.post('/api/register').send({name:'sharing-bob',password:'test-only-2026'});state={schema:1,mode:'local-simulation',activeId:null,habitId:'h',habits:[{id:'h',name:'阅读',formedAt:null}],templates:{},events:[{id:'e',name:'我的作品',startedAt:0,endedAt:1,segments:[{start:0,end:1}],draft:'PRIVATE-DRAFT',notes:[{id:'n',text:'PRIVATE-NOTE',at:0}],steps:[],stepDone:{}}],nodes:[{id:'my-goal',title:'个人草图目标',goal:'画一幅可说明构思的草图。',five:'先画三条线。',domain:'创造',branch:'草图',ownership:'personal',visibility:'private',version:1,privateMemo:'PRIVATE-MEMO',methods:[{id:'m',title:'私人方法',author:'sharing-alice',versions:[{number:1,created:0,content:'PRIVATE-METHOD',five:'私人的起步',resource:''}]}],versions:[{goal:'PRIVATE-OLD-GOAL'}]}]};await save();const saved=await alice.post('/api/review-private-targets').set('If-Match',revision).send({nodeId:'my-goal',sourceVersion:1});expect(saved.status).toBe(201);privateRef=saved.body.binding.ref});
afterEach(()=>{if(!path.resolve(directory).startsWith(path.resolve(os.tmpdir())+path.sep))throw Error('Unexpected fixture');fs.rmSync(directory,{recursive:true,force:true})});
it('does not reuse old or unversioned light-up evidence to publish tutorials for a revised public target',async()=>{
 const first=(await share()).body.node;
 async function confirm(node,id,start){
  const knowledge={nodeId:node.id,nodeTitle:node.title,nodeGoal:node.goal,nodeVersion:node.sourceVersion,nodeDomain:node.domain,nodeBranch:node.branch,nodeOwnership:'personal',nodeVisibility:'public',methodId:null,methodTitle:'独立尝试',version:null,content:'',resource:'',five:node.five,targetServiceReference:{treeId:node.treeId,nodeId:node.id,targetVersion:node.version,sourceVersion:node.sourceVersion,ownerId:node.ownerId}};
  state.events.push({id,name:node.title,startedAt:start,endedAt:start+10,segments:[{start,end:start+10}],steps:[],stepDone:{},draft:'PRIVATE-PRACTICE-DRAFT',notes:[],knowledge});
  state.lights=[...(state.lights||[]),{id:'light-'+id,eventId:id,nodeId:node.id,confirmed:true,public:false,result:'已完成这个版本的目标',evidence:'本人已核对该版本的结果'}];await save();
  const result=await alice.post('/api/review-practices').set('If-Match',revision).send({eventId:id,practiceMode:'independent',tutorialId:null,tutorialVersion:null,lightId:'light-'+id,visibility:'private'});expect(result.status).toBe(201);return result.body.record;
 }
 const original=await confirm(first,'old-public-practice',100);
 const method=node=>({treeId:node.treeId,nodeId:node.id,targetVersion:node.version,title:'这个目标的方法',method:'按已实践的目标逐步完成并核对结果。',startAction:'先完成第一个步骤。',resources:[{label:'练习材料',url:'https://example.com/practice',affiliate:false,optional:false},{label:'可选材料',url:'https://example.com/extra',affiliate:true,optional:true}],visibility:'public'});
 const tutorial=(await alice.post('/api/tutorials').send(method(first))).body.tutorial;expect(tutorial.id).toBeTruthy();
 const privateTutorial=await alice.post('/api/tutorials').send({...method(first),title:'仅本人可见的方法',method:'PRIVATE-TUTORIAL-CONTENT',visibility:'private'});expect(privateTutorial.status).toBe(201);
 const firstRead=await bob.get('/api/review-visible-targets/tutorials').query({nodeId:first.id});expect(firstRead.status).toBe(200);expect(firstRead.body.tutorials.map(t=>t.id)).toEqual([tutorial.id]);expect(firstRead.body.tutorials[0].targetSnapshot.version).toBe(first.version);expect(firstRead.body.tutorials[0].targetSnapshot.goal).toBe(first.goal);
 const tutorialFile=path.join(directory,'tutorials.json'),tutorialData=JSON.parse(fs.readFileSync(tutorialFile,'utf8')),earliest=tutorialData.find(t=>t.id===tutorial.id).versions[0];earliest.createdAt='2024-01-01T00:00:00.000Z';fs.writeFileSync(tutorialFile,JSON.stringify(tutorialData));
 const privateAgain=await alice.patch('/api/tutorials/'+tutorial.id).set('If-Match',tutorial.version).send({visibility:'private'});expect(privateAgain.status).toBe(200);expect((await bob.get('/api/review-visible-targets/tutorials').query({nodeId:first.id})).body.tutorials).toHaveLength(0);
 const republished=await alice.patch('/api/tutorials/'+tutorial.id).set('If-Match',privateAgain.body.tutorial.version).send({visibility:'public',targetVersion:first.version});expect(republished.status).toBe(200);expect(republished.body.tutorial.version).toBe(tutorial.version);const latestDate=republished.body.tutorial.versions.at(-1).createdAt;
 const reopened=(await bob.get('/api/review-visible-targets/tutorials').query({nodeId:first.id})).body.tutorials[0];expect(reopened.createdAt).toBe(latestDate);expect(reopened.createdAt).not.toBe(earliest.createdAt);expect(republished.body.tutorial.versions[0]).toEqual(earliest);expect((await bob.get('/api/review-public-tutorials/one').query({id:tutorial.id})).body.tutorial.createdAt).toBe(latestDate);
 expect(firstRead.body.tutorials[0].resources).toEqual(tutorial.resources);expect(JSON.stringify(firstRead.body)).not.toContain('PRIVATE-TUTORIAL-CONTENT');expect((await bob.get('/api/review-visible-targets/tutorials').set('X-Action-Account',first.ownerId).query({nodeId:first.id})).status).toBe(409);
 const repeatBody={...method(first),title:'稳定提交的私人教程',visibility:'private',requestId:'stable-create-request'};const initial=await alice.post('/api/tutorials').send(repeatBody);expect(initial.status).toBe(201);const repeated=await alice.post('/api/tutorials').send(repeatBody);expect(repeated.status).toBe(200);expect(repeated.body.repeated).toBe(true);expect(repeated.body.tutorial.id).toBe(initial.body.tutorial.id);const beforeReuse=fs.readFileSync(path.join(directory,'tutorials.json'),'utf8');expect((await alice.post('/api/tutorials').send({...repeatBody,method:'重复提交标识不能指向另一内容'})).body.code).toBe('VISIBLE_TUTORIAL_REQUEST_REUSED');expect(fs.readFileSync(path.join(directory,'tutorials.json'),'utf8')).toBe(beforeReuse);expect((await alice.patch('/api/tutorials/'+initial.body.tutorial.id).set('If-Match',initial.body.tutorial.version).send({method:'这份已保存教程随后被修订'})).status).toBe(200);expect((await alice.post('/api/tutorials').send(repeatBody)).body.code).toBe('VISIBLE_TUTORIAL_REQUEST_CHANGED');expect((await alice.delete('/api/tutorials/'+initial.body.tutorial.id)).status).toBe(200);expect((await alice.post('/api/tutorials').send(repeatBody)).body.code).toBe('VISIBLE_TUTORIAL_REQUEST_ARCHIVED');
 expect((await bob.get('/api/review-visible-targets/tutorials').set('Origin','https://not-authorized.example').query({nodeId:first.id})).status).toBe(403);
 state.nodes[0].version=2;state.nodes[0].goal='画完整透视结构，并解释光影关系。';await save();
 const privatePlan=(await alice.get('/api/review-private-targets')).body.current[0];
 expect((await alice.post('/api/review-private-targets').set('If-Match',revision).set('If-Target-Match',privatePlan.revision).send({nodeId:'my-goal',sourceVersion:2})).status).toBe(201);
 const second=(await share()).body.node;expect(second.version).not.toBe(first.version);
 expect((await bob.get('/api/review-visible-targets/tutorials').query({nodeId:second.id})).body.tutorials).toEqual([]);
 const tutorialBytes=fs.readFileSync(path.join(directory,'tutorials.json'),'utf8');const stale=await alice.post('/api/tutorials').send({...method(first),visibility:'private'});expect(stale.status).toBe(409);expect(stale.body.code).toBe('VISIBLE_TUTORIAL_TARGET_CHANGED');expect(fs.readFileSync(path.join(directory,'tutorials.json'),'utf8')).toBe(tutorialBytes);
 const rejected=await alice.post('/api/tutorials').send(method(second));expect(rejected.status).toBe(403);expect(rejected.body.code).toBe('KNOWLEDGE_LIGHT_REQUIRED');
 expect((await alice.patch('/api/tutorials/'+tutorial.id).set('If-Match',tutorial.version).send({method:'仅凭旧目标完成记录的新公开教程'})).status).toBe(403);
 expect((await alice.post('/api/records').send({treeId:second.treeId,nodeId:second.id,text:'没有绑定版本的普通点亮',lightUp:true,visibility:'private'})).status).toBe(201);
 expect((await alice.post('/api/tutorials').send(method(second))).status).toBe(403);
 expect((await alice.patch('/api/tutorials/'+tutorial.id).set('If-Match',tutorial.version).send({visibility:'private'})).status).toBe(200);
 await confirm(second,'current-public-practice',200);
 const newer=await alice.post('/api/tutorials').send(method(second));expect(newer.status).toBe(201);expect(newer.body.tutorial.targetSnapshot.version).toBe(second.version);
 expect((await bob.get('/api/review-visible-targets/tutorials').query({nodeId:second.id})).body.tutorials.map(t=>t.id)).toEqual([newer.body.tutorial.id]);
 const privateOld=(await alice.get('/api/tutorials')).body.tutorials.find(t=>t.id===tutorial.id);const wrongTarget=await alice.patch('/api/tutorials/'+tutorial.id).set('If-Match',privateOld.version).send({visibility:'public',targetVersion:second.version});expect(wrongTarget.status).toBe(409);expect(wrongTarget.body.code).toBe('VISIBLE_TUTORIAL_NEW_TARGET_REQUIRED');
 const oldVersion=await alice.get('/api/tutorials/'+tutorial.id+'/versions/'+tutorial.version);expect(oldVersion.status).toBe(200);expect(oldVersion.body.tutorial.targetSnapshot.version).toBe(first.version);expect(oldVersion.body.tutorial.targetSnapshot.goal).toBe(first.goal);
 expect((await bob.post('/api/tutorials').send(method(second))).status).toBe(403);
 const old=(await alice.get('/api/records')).body.records.find(r=>r.id===original.id);expect(old.targetVersion).toBe(first.version);expect(old.sourceSnapshot.nodeGoal).toBe(first.goal);expect(JSON.stringify((await bob.get('/api/records')).body)).not.toContain('PRIVATE-PRACTICE-DRAFT');
 await share('withdraw');const withdrawn=await alice.post('/api/tutorials').send(method(second));expect(withdrawn.status).toBe(403);expect(withdrawn.body.code).toBe('KNOWLEDGE_TARGET_UNAVAILABLE');
 expect((await bob.get('/api/review-visible-targets/tutorials').query({nodeId:second.id})).status).toBe(404);
 expect((await alice.post('/api/tutorials').send({...method(second),visibility:'private'})).status).toBe(201);
});
it('preserves tutorial files and refuses public contribution when the public target hash cannot be verified',async()=>{
 const node=(await share()).body.node,tutorials=path.join(directory,'tutorials.json');
 const draft={treeId:node.treeId,nodeId:node.id,targetVersion:node.version,title:'私人草稿',method:'保留这份私人方法。',visibility:'private'};expect((await alice.post('/api/tutorials').send(draft)).status).toBe(201);const before=fs.readFileSync(tutorials,'utf8');
 const file=path.join(directory,'custom-nodes.json'),store=JSON.parse(fs.readFileSync(file,'utf8'));store.nodes.find(n=>n.id===node.id).goal='被外部改动、与版本哈希不一致的目标';const damaged=JSON.stringify(store);fs.writeFileSync(file,damaged);
 const refused=await alice.post('/api/tutorials').send({...draft,visibility:'public'});expect(refused.status).toBe(503);expect(refused.body.code).toBe('KNOWLEDGE_PUBLICATION_UNAVAILABLE');expect(fs.readFileSync(tutorials,'utf8')).toBe(before);expect(fs.readFileSync(file,'utf8')).toBe(damaged);
});
it('publishes only the explicitly reviewed definition and keeps private history and individual ownership',async()=>{const before=(await alice.get('/api/action-state')).body.state,plan=await alice.get('/api/review-target-sharing').query({nodeId:'my-goal'});expect(plan.body.excluded).toContain('私人教程');const published=await share();expect(published.status).toBe(201);const node=published.body.node;expect(node.ownership).toBe('personal');expect(node.goal).toBe(state.nodes[0].goal);const publicNodes=(await bob.get('/api/nodes')).body.nodes;expect(publicNodes.find(n=>n.id===node.id).goal).toBe(node.goal);expect(publicNodes.some(n=>n.id===privateRef.nodeId)).toBe(false);const serialized=JSON.stringify(publicNodes);for(const text of ['PRIVATE-DRAFT','PRIVATE-NOTE','PRIVATE-MEMO','PRIVATE-METHOD','PRIVATE-OLD-GOAL'])expect(serialized).not.toContain(text);expect((await alice.get('/api/action-state')).body.state).toEqual(before);expect((await alice.get('/api/review-private-targets')).body.bindings[0].ref).toEqual(privateRef)});
it('requires consent and rejects caller-supplied replacement content',async()=>{expect((await share('publish',false)).status).toBe(403);expect((await share('publish',true,{goal:'Injected public text'})).status).toBe(400);expect((await bob.get('/api/nodes')).body.nodes.some(n=>n.title===state.nodes[0].title)).toBe(false)});
it('withdraws public visibility without losing either version or changing the private origin',async()=>{const published=(await share()).body.node;const result=await share('withdraw');expect(result.status).toBe(200);expect(result.body.node.visibility).toBe('private');expect(result.body.node.versions).toEqual(published.versions);expect((await bob.get('/api/nodes')).body.nodes.some(n=>n.id===published.id)).toBe(false);expect((await alice.get('/api/review-private-targets')).body.bindings[0].ref).toEqual(privateRef);expect((await share('withdraw')).body.repeated).toBe(true);expect((await share()).status).toBe(201)});
it('keeps publication retries idempotent and rejects stale service revisions',async()=>{const first=await share(),file=path.join(directory,'custom-nodes.json'),before=fs.readFileSync(file,'utf8');expect((await share()).body.repeated).toBe(true);expect(fs.readFileSync(file,'utf8')).toBe(before);const wrong=await alice.post('/api/review-target-sharing').set('If-Match',revision).set('If-Target-Match','stale').send({nodeId:'my-goal',sourceVersion:1,action:'withdraw',consent:true});expect(wrong.status).toBe(409);expect(fs.readFileSync(file,'utf8')).toBe(before);expect(first.body.node.visibility).toBe('public')});
it('refuses another account and unsaved or externally changed private definitions',async()=>{expect((await bob.get('/api/review-target-sharing').query({nodeId:'my-goal'})).status).toBe(409);state.nodes[0].goal='尚未保存的新定义';state.nodes[0].version=2;await save();expect((await share()).status).toBe(409);expect((await bob.get('/api/nodes')).body.nodes.some(n=>n.title===state.nodes[0].title)).toBe(false)});
it('publishes a reviewed new definition without rewriting the first public version or private bindings',async()=>{const first=(await share()).body.node,oldVersion=first.versions[0],oldBindings=(await alice.get('/api/review-private-targets')).body.bindings;state.nodes[0].goal='明确修订的第二版草图目标。';state.nodes[0].version=2;await save();const current=(await alice.get('/api/review-private-targets')).body.current[0];expect((await alice.post('/api/review-private-targets').set('If-Match',revision).set('If-Target-Match',current.revision).send({nodeId:'my-goal',sourceVersion:2})).status).toBe(201);const second=await share();expect(second.status).toBe(201);expect(second.body.node.id).toBe(first.id);expect(second.body.node.versions).toHaveLength(2);expect(second.body.node.versions[0]).toEqual(oldVersion);expect(second.body.node.goal).toBe(state.nodes[0].goal);expect((await alice.get('/api/review-private-targets')).body.bindings[0]).toEqual(oldBindings[0])});
it('discovers only current public definitions and never returns private payloads or withdrawn targets',async()=>{expect((await bob.get('/api/review-visible-targets')).body.total).toBe(0);const node=(await share()).body.node;const list=await bob.get('/api/review-visible-targets').query({query:'草图'});expect(list.status).toBe(200);expect(list.body.targets).toHaveLength(1);expect(list.body.targets[0].nodeId).toBe(node.id);expect(Object.keys(list.body.targets[0])).not.toContain('publicationOrigin');expect(JSON.stringify(list.body)).not.toContain('PRIVATE-');expect((await bob.get('/api/review-visible-targets').query({query:'not-found'})).body.targets).toEqual([]);expect((await bob.get('/api/review-visible-targets/one').query({nodeId:privateRef.nodeId})).status).toBe(404);await share('withdraw');expect((await bob.get('/api/review-visible-targets')).body.targets).toEqual([]);expect((await bob.get('/api/review-visible-targets/one').query({nodeId:node.id})).status).toBe(404)});
it('rejects corrupt public definitions instead of treating a similar title as the original target',async()=>{const node=(await share()).body.node,file=path.join(directory,'custom-nodes.json'),store=JSON.parse(fs.readFileSync(file,'utf8'));store.nodes.find(n=>n.id===node.id).goal='与实际发布版本不一致';fs.writeFileSync(file,JSON.stringify(store));expect((await bob.get('/api/review-visible-targets')).status).toBe(409);expect((await bob.get('/api/review-visible-targets/one').query({nodeId:node.id})).status).toBe(409)});
it('paginates same-name targets by identity and rejects a cursor only when public contents change',async()=>{await share();for(let i=1;i<=2;i++){const n={...structuredClone(state.nodes[0]),id:'same-name-'+i};state.nodes.push(n);await save();expect((await alice.post('/api/review-private-targets').set('If-Match',revision).send({nodeId:n.id,sourceVersion:1})).status).toBe(201);expect((await share('publish',true,{nodeId:n.id})).status).toBe(201)}const first=(await bob.get('/api/review-visible-targets').query({limit:1})).body;expect(first.total).toBe(3);expect(first.targets).toHaveLength(1);state.nodes[0].privateMemo='NEW-PRIVATE-EDIT';await save();const second=(await bob.get('/api/review-visible-targets').query({limit:1,cursor:first.nextCursor})).body,third=(await bob.get('/api/review-visible-targets').query({limit:1,cursor:second.nextCursor})).body;expect(new Set([first.targets[0].nodeId,second.targets[0].nodeId,third.targets[0].nodeId]).size).toBe(3);expect(third.nextCursor).toBeNull();expect(JSON.stringify(second)).not.toContain('NEW-PRIVATE-EDIT');await share('withdraw');expect((await bob.get('/api/review-visible-targets').query({limit:1,cursor:first.nextCursor})).body.code).toBe('VISIBLE_TARGET_CURSOR_CHANGED')});
it('keeps a reader private historical practice readable after the author withdraws the target',async()=>{const node=(await share()).body.node,k={nodeId:node.id,nodeTitle:node.title,nodeGoal:node.goal,nodeVersion:1,nodeDomain:node.domain,nodeBranch:node.branch,nodeOwnership:'personal',nodeVisibility:'public',methodId:null,methodTitle:'独立尝试',version:null,content:'',resource:'',five:node.five,targetServiceReference:{treeId:node.treeId,nodeId:node.id,targetVersion:node.version,sourceVersion:1,ownerId:node.ownerId}};const reader={schema:1,mode:'local-simulation',activeId:null,habitId:'h',habits:[{id:'h',name:'阅读',formedAt:null}],templates:{},nodes:[],events:[{id:'reader-event',name:node.title,startedAt:0,endedAt:1000,segments:[{start:0,end:1000}],steps:[],stepDone:{},draft:'READER-DRAFT',notes:[],knowledge:k}]};const old=(await bob.get('/api/action-state')).body;const saved=await bob.put('/api/action-state').set('If-Match',old.revision).send({format:FORMAT,data:reader});expect(saved.status).toBe(200);const body={eventId:'reader-event',practiceMode:'independent',tutorialId:null,tutorialVersion:null,visibility:'private'},practice=await bob.post('/api/review-practices').set('If-Match',saved.body.revision).send(body);expect(practice.status).toBe(201);await share('withdraw');expect((await bob.get('/api/review-visible-targets/one').query({nodeId:node.id})).status).toBe(404);const records=(await bob.get('/api/records')).body.records;expect(records.find(r=>r.id===practice.body.record.id)?.sourceSnapshot.nodeGoal).toBe(node.goal);expect(records.find(r=>r.id===practice.body.record.id)?.historicalTargetOnly).toBe(true);expect((await alice.get('/api/records')).body.records.some(r=>r.id===practice.body.record.id)).toBe(false);expect((await bob.get('/api/records').query({nodeId:'another-node'})).body.records).toEqual([]);expect((await bob.post('/api/review-practices').set('If-Match',saved.body.revision).send(body)).status).toBe(400);expect((await bob.get('/api/review-practices')).body.receipts[0].record.id).toBe(practice.body.record.id);const readerId=(await bob.get('/api/me')).body.user.id,archiveFile=path.join(directory,'practice-receipts',readerId+'.json'),archiveBytes=fs.readFileSync(archiveFile,'utf8');fs.writeFileSync(archiveFile,'{damaged');const unreadable=await bob.get('/api/records');expect(unreadable.status).toBe(500);expect(unreadable.body.code).toBe('PRACTICE_HISTORY_UNREADABLE');expect(fs.readFileSync(archiveFile,'utf8')).toBe('{damaged');fs.writeFileSync(archiveFile,archiveBytes);expect((await bob.get('/api/records').set('X-Action-Account',privateRef.ownerId)).status).toBe(409);const recordFile=path.join(directory,'records.json'),rawRecords=JSON.parse(fs.readFileSync(recordFile,'utf8'));rawRecords.push({...practice.body.record,id:'untracked-private-record',eventId:'untracked-event'});fs.writeFileSync(recordFile,JSON.stringify(rawRecords));expect((await bob.get('/api/records')).body.records.some(r=>r.id==='untracked-private-record')).toBe(false);expect((await bob.delete('/api/records/'+practice.body.record.id)).status).toBe(200);expect((await bob.get('/api/records')).body.records.some(r=>r.id===practice.body.record.id)).toBe(false)});
